import os
import requests
from flask import Flask, request, redirect, url_for, session

app = Flask(__name__)
app.secret_key = os.urandom(24)

# Auth0 domain and client details
AUTH0_DOMAIN = os.environ.get("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.environ.get("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.environ.get("AUTH0_CLIENT_SECRET")
AUTH0_CALLBACK_URL = os.environ.get("AUTH0_CALLBACK_URL", "http://localhost:5000/callback")

@app.route("/")
def home():
    if "user" in session:
        return f"Hello, {session['user']['name']}! <a href='/logout'>Logout</a>"
    return '<a href="/login">Login with Auth0</a>'

@app.route("/login")
def login():
    authorize_url = (
        f"https://{AUTH0_DOMAIN}/authorize?"
        f"response_type=code&"
        f"client_id={AUTH0_CLIENT_ID}&"
        f"redirect_uri={AUTH0_CALLBACK_URL}&"
        f"scope=openid profile email"
    )
    return redirect(authorize_url)

@app.route("/callback")
def callback():
    code = request.args.get("code")
    if not code:
        return "Authorization code missing", 400

    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    headers = {"Content-Type": "application/x-www-form-urlencoded"}
    payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": AUTH0_CALLBACK_URL,
    }

    try:
        response = requests.post(token_url, headers=headers, data=payload)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        token_info = response.json()

        access_token = token_info.get("access_token")
        id_token = token_info.get("id_token")

        if not access_token or not id_token:
            return "Failed to retrieve access or ID token", 500

        # Optionally, fetch user info using the access token
        userinfo_url = f"https://{AUTH0_DOMAIN}/userinfo"
        userinfo_response = requests.get(userinfo_url, headers={"Authorization": f"Bearer {access_token}"})
        userinfo_response.raise_for_status()
        user_profile = userinfo_response.json()

        session["user"] = user_profile
        return redirect(url_for("home"))

    except requests.exceptions.RequestException as e:
        return f"Error exchanging code for tokens: {e}", 500

@app.route("/logout")
def logout():
    session.pop("user", None)
    # Redirect to Auth0 logout endpoint to clear Auth0 session as well
    logout_url = (
        f"https://{AUTH0_DOMAIN}/v2/logout?"
        f"client_id={AUTH0_CLIENT_ID}&"
        f"returnTo={url_for('home', _external=True)}"
    )
    return redirect(logout_url)

if __name__ == "__main__":
    # Ensure environment variables are set for a real application
    # export AUTH0_DOMAIN="YOUR_AUTH0_DOMAIN"
    # export AUTH0_CLIENT_ID="YOUR_AUTH0_CLIENT_ID"
    # export AUTH0_CLIENT_SECRET="YOUR_AUTH0_CLIENT_SECRET"
    # export AUTH0_CALLBACK_URL="http://localhost:5000/callback"
    app.run(debug=True)
